arguments.command:
curl -s -X POST "https://slack.com/api/users.list" -H "Content-Type: application/x-www-form-urlencoded" --data "token=<TOKEN>&limit=1000" | python3 -c "
import json,sys
d = json.load(sys.stdin)
if not d.get('ok'): print('ERROR:', d); sys.exit(1)
for u in d['members']:
    real = u.get('real_name','')
    if 'aisha' in real.lower() or 'khan' in real.lower():
        print(u['id'], '|', real, '|', u.get('profile',{}).get('display_name',''))
"

